-- OnionEye — Demo media seed for the dashboard MEDIA tab / EVIDENCE MEDIA strip.
--
-- Generated by /tmp/gen_media_seed.py and committed so the judge demo is
-- reproducible. The rows carry evidence = 'media_demo_seed' so they can be deleted in
-- one statement if the demo gallery is no longer wanted. Idempotent: safe to
-- run repeatedly, never duplicates an image src.

-- 1) Evidence attached to existing actors (clicking a thumbnail opens the dossier):
INSERT INTO image_hashes (actor_id, perceptual_hash, evidence, detected_at)
SELECT a.actor_id, v.src, 'media_demo_seed', now() - make_interval(hours => v.ord)
FROM actors a
JOIN (VALUES
  ('TERM:0x_shadow_lord', 1, 'data:image/svg+xml;base64,'),
  ('TERM:0x_shadow_lord', 2, 'data:image/svg+xml;base64,'),
  ('TERM:escrow', 3, 'data:image/svg+xml;base64,'),
  ('TERM:escrow', 4, 'data:image/svg+xml;base64,'),
  ('TERM:exploit', 5, 'data:image/svg+xml;base64,'),
  ('TERM:exploit', 6, 'data:image/svg+xml;base64,'),
  ('TERM:pgp', 7, 'data:image/svg+xml;base64,'),
  ('TERM:pgp', 8, 'data:image/svg+xml;base64,')
) AS v(handle, ord, src) ON a.primary_handle = v.handle
WHERE NOT EXISTS (SELECT 1 FROM image_hashes ih WHERE ih.perceptual_hash = v.src);

-- 2) Orphan evidence (no owning actor yet — thumbnail opens the full-viewer overlay):
INSERT INTO image_hashes (perceptual_hash, evidence, detected_at)
SELECT v.src, 'media_demo_seed', now() - make_interval(hours => v.ord)
FROM (VALUES
  (9, 'data:image/svg+xml;base64,'),
  (10, 'data:image/svg+xml;base64,')
) AS v(ord, src)
WHERE NOT EXISTS (SELECT 1 FROM image_hashes ih WHERE ih.perceptual_hash = v.src);
